// Compat: el resto del código (y el Excel) trabaja con nombres sueltos.
export const AGENCIAS_SHALOM: string[] = AGENCIAS.map((a) => a.l);

const _n = (s: string) =>
  String(s ?? "").toUpperCase().normalize("NFD")
    .replace(/[̀-ͯ]/g, "").replace(/[^A-Z0-9]+/g, " ").trim();

// Las agencias que el texto puede estar nombrando. Compara contra el NOMBRE de
// la agencia, no contra su ciudad: "miraflores chiclayo" identifica una oficina,
// "chiclayo" no (ver agenciasDeCiudad).
export function candidatasAgencia(texto: string): string[] {
  const t = _n(texto);
  if (!t) return [];
  const exact = AGENCIAS_SHALOM.filter((a) => _n(a) === t);
  if (exact.length) return exact;
  // El nombre de la oficina tiene que aparecer como PALABRA, no como pedazo de otra.
  // Medido: «hola, mi hermana COMPRO esto y le funciono… soy de arequipa cerro colorado»
  // → dentro de "compro" está "PRO", que es una oficina de Los Olivos, y el motor le selló
  // esa sede a un cliente de Arequipa. Con `includes` a secas, cualquier oficina de nombre
  // corto (PRO, SUR, ICA, LIMA) se cuela dentro de una palabra cualquiera del mensaje.
  const _palabra = (texto: string, nombre: string) =>
    new RegExp("(^|[^A-Z0-9])" + nombre.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "([^A-Z0-9]|$)").test(texto);
  // El sentido inverso (el cliente escribe menos que el nombre completo: "atahualpa" para
  // "AV. ATAHUALPA") solo vale con algo suficientemente específico: con dos o tres letras
  // sueltas no se elige una agencia.
  return AGENCIAS_SHALOM.filter((a) => { const na = _n(a); return na && (_palabra(t, na) || (t.length >= 4 && na.includes(t))); });
}

// El cliente no escribe "CHICLAYO": escribe "la sede de Chiclayo nomás". Sin quitarle
// ese ruido, la ciudad no calzaba con ninguna y el motivo salía equivocado ("dijo una
// oficina que no está en la lista" cuando en realidad dijo su ciudad, donde hay varias).
const RUIDO_UBIC =
  /\b(LA|EL|LOS|LAS|UN|UNA|DE|DEL|EN|QUE|ESTA|QUEDA|POR|AHI|ALLA|MI|SU|NOMAS|SEDE|SEDES|OFICINA|OFICINAS|AGENCIA|AGENCIAS|SHALOM|SUCURSAL|LOCAL|TIENDA|PUNTO|CIUDAD)\b/g;
const _sinRuido = (s: string) => _n(s).replace(RUIDO_UBIC, " ").replace(/\s+/g, " ").trim();

// Las oficinas que hay en una ciudad. Lo que el cliente llama "mi ciudad" puede
// ser su distrito ("Pomalca"), su provincia ("Chiclayo") o su departamento
// ("Lambayeque"), así que se busca en los tres y se devuelve el corte MÁS FINO
// que dé resultados: si dice Chiclayo interesan las 4 del distrito, no las 14 de
// toda la provincia.
// Las oficinas de una ciudad, mirando SOLO los campos de lugar (distrito, provincia,
// departamento). Separado del público de abajo a propósito: aquel, si no encuentra
// nada, cae a "que la ciudad aparezca dentro del NOMBRE de la agencia", y ese último
// intento sirve para listarle opciones al cliente pero NO para decidir si lo que dijo
// era una ciudad o el nombre de una oficina.
function _deCiudadEstricto(ciudad: string): Agencia[] {
  const c = _n(ciudad);
  if (!c) return [];
  const limpio = _sinRuido(ciudad);
  if (limpio && limpio !== c) {
    const porLimpio = _deCiudadEstricto(limpio);
    if (porLimpio.length) return porLimpio;
  }
  const porDist = AGENCIAS.filter((a) => _n(a.t) === c);
  if (porDist.length) return porDist;
  const porProv = AGENCIAS.filter((a) => _n(a.p) === c);
  if (porProv.length) return porProv;
  return AGENCIAS.filter((a) => _n(a.d) === c);
}

// 🏢 Puntos del volcado que NO son un mostrador donde un cliente va a recoger su paquete:
// son el área corporativa y un almacén. Ofrecérselos a alguien manda a una persona a una
// puerta donde no la van a atender. Medido: a un cliente de Pucusana (distrito de Lima sin
// reparto propio) la lista de oficinas le salió "01 De Mayo, Almacenes Bsf, Ancón, Area
// Shalom Empresas…". Se ocultan solo al OFRECER: si el cliente nombra una —porque Shalom se
// la indicó— `sedeReconocida`/`candidatasAgencia` la siguen reconociendo igual.
const NO_OFRECER = new Set(["area shalom empresas", "almacenes bsf"]);
const _ofrecible = (a: Agencia) => !NO_OFRECER.has(_n(a.l));

export function agenciasDeCiudad(ciudad: string): Agencia[] {
  const estricto = _deCiudadEstricto(ciudad).filter(_ofrecible);
  if (estricto.length) return estricto;
  // Último intento: que la ciudad aparezca dentro del nombre de la agencia
  // ("HUANCAYO" → "HUANCAYO CO", "AEROPUERTO HUANCAYO").
  const c = _n(ciudad);
  return c ? AGENCIAS.filter((a) => _n(a.l).includes(c) && _ofrecible(a)) : [];
}

// ¿La oficina que dijo el cliente alcanza para despachar, o hay que confirmársela?
// Devuelve null si es segura, o el motivo para que un humano la coordine.
//
// Sigue valiendo la regla de siempre: esto CONFIRMA, no descarta. La lista es un
// volcado con fecha, no la verdad viva de Shalom.
export function sedeReconocida(sede: string, ciudad: string): string | null {
  return _resuelveSede(sede, ciudad).motivo;
}

// La oficina EXACTA que eligió, o null si no se puede saber con certeza. Sale del
// mismo razonamiento que `sedeReconocida` a propósito: son la misma pregunta vista
// de dos lados —"¿es segura?" y "¿cuál es?"— y tenerlas en dos copias era garantía
// de que un día dijeran cosas distintas. Se usa para mandarle la ficha de su sede.
export function agenciaExacta(sede: string, ciudad: string): Agencia | null {
  const r = _resuelveSede(sede, ciudad);
  return r.motivo ? null : r.a;
}

// Nombre de archivo estable para la ficha de una oficina. Lleva departamento,
// provincia y distrito además del nombre porque hay agencias que se llaman igual
// en sitios distintos ("Atahualpa", "Av. Ejército") y una sola palabra las mezcla.
export function slugAgencia(a: Agencia): string {
  return [a.d, a.p, a.t, a.l].map((x) => _n(x)).join("-")
    .replace(/[^A-Z0-9]+/g, "-").replace(/^-|-$/g, "").toLowerCase();
}

function _resuelveSede(sede: string, ciudad: string): { motivo: string | null; a: Agencia | null } {
  const s = String(sede ?? "").trim();
  const _no = (motivo: string) => ({ motivo, a: null });
  const _si = (a: Agencia | null) => ({ motivo: null, a });
  if (!s) {
    return _no(String(ciudad ?? "").trim()
      ? "no dijo la oficina — confírmala con él antes de despachar"
      : "falta la sede/agencia de destino — confírmala");
  }
  // ⚠️ La coincidencia por nombre NO alcanza: hay agencias que se llaman igual o
  // parecido en departamentos distintos. Medido — una clienta de AREQUIPA pidió
  // "Shalom Arequipa Av Ejercito" y calzó con AV EJERCITO… que está en TACNA. El
  // pedido salió sin bandera y el paquete iba a cruzar medio país. Si sabemos su
  // ciudad, la candidata tiene que estar EN esa zona.
  const enSuZona = (a: Agencia) => {
    const c = _sinRuido(ciudad) || _n(ciudad);
    if (!c) return true;                       // sin ciudad no hay con qué filtrar
    return _n(a.t) === c || _n(a.p) === c || _n(a.d) === c || _n(a.l).includes(c);
  };
  const todas = candidatasAgencia(s);
  const deLaZona = AGENCIAS.filter((a) => todas.includes(a.l) && enSuZona(a));
  const cs = deLaZona.length ? deLaZona.map((a) => a.l) : [];
  if (todas.length && !deLaZona.length) {
    return _no(`la oficina que dijo ("${s}") no es de su zona — confírmasela antes de despachar`);
  }
  // Nombró una agencia tal cual.
  const _tal = deLaZona.find((a) => _n(a.l) === _n(s));
  if (_tal) return _si(_tal);
  // 🏙️ ¿Lo que dijo es una CIUDAD? Va ANTES del parecido de nombre, y por eso se mira
  // con `_deCiudadEstricto` (distrito/provincia/departamento, sin el "que la ciudad
  // aparezca dentro del nombre de la agencia", que es un último recurso para LISTARLE
  // opciones, no para decidir qué dijo).
  // Medido: dijo "Chiclayo" y el chat le mostró bien las CUATRO oficinas del distrito,
  // pero la bandera del pedido decía "hay 2 oficinas que calzan" — las dos que llevan
  // "Chiclayo" dentro del nombre (Aeropuerto y Miraflores). El operador leía 2 y el
  // cliente había visto 4: dos números distintos para la misma pregunta.
  const _ciudadDicha = _deCiudadEstricto(s);
  if (_ciudadDicha.length === 1) return _si(_ciudadDicha[0]);
  if (_ciudadDicha.length > 1) {
    return _no(`en ${_sinRuido(s) || s} hay ${_ciudadDicha.length} oficinas Shalom — confirma con él a cuál va`);
  }
  // Su texto apunta a una sola.
  if (cs.length === 1) return _si(deLaZona[0]);
  if (cs.length > 1) {
    return _no(`hay ${cs.length} oficinas Shalom que calzan con "${s}" — confirma la exacta`);
  }
  // No nombró ninguna agencia. ¿Será que dijo su ciudad?
  const enCiudad = agenciasDeCiudad(s);
  if (enCiudad.length === 1) return _si(enCiudad[0]);  // esa ciudad tiene una sola
  if (enCiudad.length > 1) {
    return _no(`en ${_sinRuido(s) || s} hay ${enCiudad.length} oficinas Shalom — confirma con él a cuál va`);
  }
  return _no("dijo una oficina que no está en la lista — confírmasela antes de despachar");
}

// Los OTROS distritos de su misma provincia donde también hay oficina. Cuando el
// cliente dice "soy de Chiclayo" se le muestran las 4 del distrito, que son las
// que le sirven… salvo que viva en Pimentel o Pomalca, que son provincia de
// Chiclayo y tienen la suya propia a la vuelta de la esquina. Con esto el bot
// puede ofrecérselas en vez de mandarlo al centro.
export function otrosDistritosConAgencia(ciudad: string): string[] {
  const c = _sinRuido(ciudad) || _n(ciudad);
  if (!c) return [];
  const enDist = AGENCIAS.filter((a) => _n(a.t) === c);
  if (!enDist.length) return [];   // no nombró un distrito → no hay "otros" que ofrecer
  const prov = _n(enDist[0].p);
  return [...new Set(
    AGENCIAS.filter((a) => _n(a.p) === prov && _n(a.t) !== c).map((a) => a.t),
  )];
}

// 🕳️ El distrito del cliente NO tiene oficina Shalom. Con el padrón de distritos
// (distritos-peru.ts) se resuelve a qué PROVINCIA pertenece y se devuelven las
// agencias de esa provincia — que quedan en otro pueblo, y por eso el llamador
// tiene que decírselo así al cliente, nunca como si fueran "las de su ciudad".
//
// Si el nombre existe en varias provincias (hay 102 así, "Miraflores" entre
// ellos) se queda con las que SÍ tienen agencia; si aun así hay más de una
// provincia candidata, devuelve vacío: mandar un paquete a otro departamento por
// adivinar es peor que preguntarle a qué ciudad suele ir.
export function agenciasCercanasAlDistrito(
  ciudad: string,
): { prov: string; dep: string; agencias: Agencia[] } | null {
  const cands = provinciasDeDistrito(_sinRuido(ciudad) || _n(ciudad));
  if (!cands.length) return null;
  const conAgencia = cands
    // `_ofrecible`: acá también se están OFRECIENDO oficinas, así que el área corporativa y
    // el almacén quedan fuera igual que en `agenciasDeCiudad`.
    .map((c) => ({ ...c, agencias: AGENCIAS.filter((a) => _n(a.p) === _n(c.prov) && _ofrecible(a)) }))
    .filter((c) => c.agencias.length);
  if (conAgencia.length !== 1) return null;
  return conAgencia[0];
}
